// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address bob = address(0x1234);
        vm.prank(bob);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
        vm.prank(address(0));
        c.transferOwnership(bob);
        assertEq(c.owner(), bob);
    }
}
